# Clones Ktor at the probe's base commit, applies the probe patch and runs it on mingwX64 (WinHttp + Curl).
# Safe to re-run: reuses an existing clone and skips the patch if it is already applied.
$ErrorActionPreference = 'Stop'
if (-not (Test-Path ktor-probe)) { git clone --filter=blob:none https://github.com/ktorio/ktor.git ktor-probe }
Set-Location ktor-probe
git checkout -q 4016bdfe32256ff82723af7259e294908e48be75
[IO.File]::WriteAllBytes("$PWD\ws-frame-probe.patch", [Convert]::FromBase64String(''))
# Native tools write warnings to stderr; with 'Stop', Windows PowerShell would treat redirected stderr as errors.
$ErrorActionPreference = 'Continue'
git apply --reverse --check ws-frame-probe.patch 2>$null
if ($LASTEXITCODE -ne 0) { git apply ws-frame-probe.patch; if ($LASTEXITCODE -ne 0) { exit 1 } }
cmd /c '.\gradlew.bat :ktor-client-tests:mingwX64Test --tests "io.ktor.client.tests.WebSocketFrameBoundariesProbe" -i > probe.log 2>&1'
Write-Host "Gradle exit code: $LASTEXITCODE (full log: $PWD\probe.log)"
Select-String -Path probe.log -Pattern 'PROBE|FAILED|What went wrong|BUILD (SUCCESSFUL|FAILED)'
